L51:     const line = JSON.stringify({ type: event.type, seq: event.seq, time: event.time, data: event.data }) + '\n';
L52:     const size = (written.get(id) ?? 0) + Buffer.byteLength(line);
L53:     if (size > MAX_TRANSCRIPT_BYTES) return; // A later reader sees an incomplete log, never a truncated line.
